// Kinetic: snowkiting page script (generated by kinetic-tools/build/build.py)
(function () {
  const PAGE = {
    key: "snowkiting",
    v1: "Physics: nailed it 🪁",
    b1: "You've got the physics of wind, air and cold. Skim the chapters for anything you missed, then see “Learn abroad” for snowkite schools. Knowing the science is a great start; it isn't the same as lessons on the snow.",
    b2: "You have the basics. Fill the gaps below, especially wind pressure and the wind window: they decide how hard the kite pulls.",
    b3: "No shame in that: this is exactly what the chapters are for. Read the ones linked below, then take the challenge again.",
    whereLabel: "Where to learn it abroad →",
    whereHref: "#abroad",
    disclaimer: "<strong>Self-check only.</strong> This quiz is a learning aid. It is not a certification or a snowkite qualification, and a high score does not mean you're ready to fly a kite on snow. Snowkiting is learned with a qualified snowkite instructor at a school; never try it alone without lessons."
  };
  const CHAPTERS = {
    "ch-wind":    "Ch 1 · Wind pressure",
    "ch-density": "Ch 2 · Altitude & cold",
    "ch-window":  "Ch 3 · The wind window",
    "ch-safety":  "Ch 4 · Depower & quick release",
    "ch-slopes":  "Ch 5 · Slopes & avalanches",
    "ch-cold":    "Ch 6 · Wind chill"
  };
  const QUESTIONS = [
    { ch: "ch-wind",
      q: "The wind doubles from 15 to 30 km/h. How does the wind pressure on the kite change?",
      o: ["It doubles", "It stays the same", "It about quadruples", "It halves"], a: 2,
      e: "Wind pressure is ½ρv². (30 ÷ 15)² = 4." },
    { ch: "ch-wind",
      q: "A gust is 50% stronger than the average wind. Roughly how much harder does the kite pull?",
      o: ["1.5 times", "About 2.25 times", "3 times", "No change"], a: 1,
      e: "1.5² = 2.25. That's why gusty days are much harder than the average wind suggests." },
    { ch: "ch-wind",
      q: "At sea level (ρ ≈ 1.23 kg/m³), what's the wind pressure at 20 km/h (5.56 m/s)?",
      o: ["About 19 Pa", "About 1.9 Pa", "About 190 Pa", "About 1,900 Pa"], a: 0,
      e: "½ × 1.227 × 5.56² ≈ 18.9 Pa. On a 9 m² kite that's a force scale of about 170 N." },
    { ch: "ch-density",
      q: "Why does the same kite in the same wind pull less at 2,000 m than at sea level?",
      o: ["The wind is always lighter in the mountains", "Snow absorbs the pull", "Kites shrink in the cold", "The air is thinner: lower pressure means lower density"], a: 3,
      e: "Density = pressure ÷ (R × T). NASA's model gives about 79.6 kPa at 2,000 m versus 101.4 kPa at sea level, so standard air there is about 82% as dense." },
    { ch: "ch-density",
      q: "At the same altitude, how does colder air change the kite's pull?",
      o: ["Colder air is denser, so it pulls a little harder", "Colder air is thinner, so it pulls less", "Temperature makes no difference", "Cold air stops kites flying"], a: 0,
      e: "At fixed pressure, density rises as absolute temperature falls: ρ = p ÷ (R × T)." },
    { ch: "ch-density",
      q: "Using NASA's Earth Atmosphere Model, about what's the standard air temperature at 2,000 m?",
      o: ["15 °C", "−20 °C", "About 2 °C", "About 30 °C"], a: 2,
      e: "T = 15.04 − 0.00649 × 2,000 ≈ 2.1 °C. Real days vary a lot around the standard." },
    { ch: "ch-window",
      q: "Why does a kite moving across the wind pull harder than a parked one?",
      o: ["It gets heavier", "The lines stretch", "Gravity increases", "It feels apparent wind: the true wind plus its own speed through the air"], a: 3,
      e: "With true wind 20 km/h and the kite crossing at 40 km/h, apparent wind ≈ √(20² + 40²) ≈ 45 km/h: about 5 times the wind pressure." },
    { ch: "ch-window",
      q: "Where do riders park the kite to stop, launch or land?",
      o: ["At the edge of the wind window, where it slows and pulls least", "In the power zone, straight downwind", "Behind them, upwind", "On the ground downwind, with the lines tight"], a: 0,
      e: "At the edge of the window the kite slows and parks, so the apparent wind and the pull drop." },
    { ch: "ch-safety",
      q: "What does pushing the bar away (depowering) do?",
      o: ["Makes the kite fly faster", "Lowers the kite's angle of attack, cutting the pull", "Releases the kite completely", "Locks the lines"], a: 1,
      e: "Air meets the kite at a smaller angle, so the force drops. A quick release and leash are for when that's not enough." },
    { ch: "ch-safety",
      q: "What does the IKA Snowkite Class require the kite leash to be able to do?",
      o: ["Pull the kite back in", "Fully flag out the kite", "Measure wind speed", "Nothing: leashes aren't required"], a: 1,
      e: "The class rules require a detachable leash with a safety release, capable of fully flagging out the kite, plus a quick release that frees the bar with one hand movement." },
    { ch: "ch-safety",
      q: "Swiss Kitesurf says its winter kites mostly have a 5th line. What is it for?",
      o: ["To fly two kites at once", "To tow a sled", "To land the kite without force and keep it on the ground", "To measure line tension"], a: 2,
      e: "The school says the 5th line lets the rider land the kite without force and keep it down, and its bars release with a 3.5 kg tug." },
    { ch: "ch-slopes",
      q: "According to SLF, what's the minimum slope angle for a slab avalanche?",
      o: ["10°", "20°", "About 30°", "50°"], a: 2,
      e: "SLF says triggering a slab avalanche needs an additional load and a slope of at least 30°." },
    { ch: "ch-slopes",
      q: "SLF's long-term figures: what share of fatal skier-triggered avalanches happened on slopes steeper than 30°?",
      o: ["43%", "97%", "50%", "3%"], a: 1,
      e: "97% steeper than 30°, 82% steeper than 35° and 43% steeper than 40°." },
    { ch: "ch-cold",
      q: "What does wind chill describe?",
      o: ["How cold exposed skin feels as moving air carries heat away", "The actual air temperature", "How cold the snow is", "How fast ice forms on lines"], a: 0,
      e: "Moving air removes heat from skin faster than still air, so skin cools as if the air were colder." },
    { ch: "ch-cold",
      q: "Using the US National Weather Service formula, about what does −10 °C feel like in a 20 km/h wind?",
      o: ["−10 °C", "−5 °C", "−30 °C", "About −18 °C"], a: 3,
      e: "13.12 + 0.6215(−10) − 11.37(20^0.16) + 0.3965(−10)(20^0.16) ≈ −17.9 °C." }
  ];

  // ---------- QUIZ RENDER ----------
  const list = document.getElementById("quiz-list");
  const dots = document.getElementById("quiz-dots");
  const prog = document.getElementById("quiz-progress");
  const progLabel = document.getElementById("quiz-progress-label");
  const warn = document.getElementById("quiz-warn");
  const resultBox = document.getElementById("quiz-result");
  let graded = false;

  function esc(s) { return s.replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  QUESTIONS.forEach((item, i) => {
    const n = i + 1;
    const div = document.createElement("div");
    div.className = "q";
    div.id = "q" + n;
    div.dataset.index = i;
    div.innerHTML =
      `<span class="qtag">${esc(CHAPTERS[item.ch].split(" · ")[1])}</span>` +
      `<span class="qnum">Question ${n} / ${QUESTIONS.length}</span>` +
      `<h3>${esc(item.q)}</h3>` +
      `<div class="opts" role="radiogroup" aria-label="Question ${n}">` +
      item.o.map((opt, j) =>
        `<label class="opt"><input type="radio" name="q${n}" value="${j}"><span>${esc(opt)}</span><span class="mark"></span></label>`
      ).join("") +
      `</div><div class="explain" aria-live="polite"></div>`;
    list.appendChild(div);

    const d = document.createElement("a");
    d.href = "#q" + n; d.textContent = n; d.id = "dot" + n;
    d.setAttribute("aria-label", "Go to question " + n);
    dots.appendChild(d);
  });

  function answeredCount() {
    return QUESTIONS.filter((_, i) => document.querySelector(`input[name="q${i + 1}"]:checked`)).length;
  }
  function updateProgress() {
    const c = answeredCount();
    prog.style.width = (c / QUESTIONS.length * 100) + "%";
    progLabel.textContent = `${c} of ${QUESTIONS.length} answered`;
  }

  list.addEventListener("change", (ev) => {
    if (graded || ev.target.type !== "radio") return;
    const q = ev.target.closest(".q");
    q.querySelectorAll(".opt").forEach(l => l.classList.toggle("sel", l.querySelector("input").checked));
    document.getElementById("dot" + (+q.dataset.index + 1)).classList.add("answered");
    updateProgress();
    warn.style.display = "none";
  });

  function grade() {
    const unanswered = QUESTIONS.length - answeredCount();
    if (unanswered > 0 && !document.getElementById("quiz-submit").dataset.confirmed) {
      warn.textContent = `${unanswered} question${unanswered > 1 ? "s" : ""} unanswered. They'll count as wrong. Press submit again to score anyway.`;
      warn.style.display = "block";
      document.getElementById("quiz-submit").dataset.confirmed = "1";
      return;
    }
    graded = true;
    let score = 0;
    const wrongChapters = new Map();
    QUESTIONS.forEach((item, i) => {
      const n = i + 1;
      const qEl = document.getElementById("q" + n);
      const picked = document.querySelector(`input[name="q${n}"]:checked`);
      const pickedIdx = picked ? +picked.value : -1;
      const right = pickedIdx === item.a;
      if (right) score++;
      else wrongChapters.set(item.ch, (wrongChapters.get(item.ch) || []).concat(n));
      qEl.classList.add("graded", right ? "right" : (picked ? "wrong" : "skipped"));
      qEl.querySelectorAll("input").forEach(inp => inp.disabled = true);
      qEl.querySelectorAll(".opt").forEach((lab, j) => {
        if (j === item.a) { lab.classList.add("correct"); lab.querySelector(".mark").textContent = "✓ correct"; }
        else if (j === pickedIdx) { lab.classList.add("incorrect"); lab.querySelector(".mark").textContent = "✗ your pick"; }
      });
      const ex = qEl.querySelector(".explain");
      ex.innerHTML = `<span class="verdict">${right ? "Correct." : (picked ? "Not quite." : "Skipped.")}</span> ${esc(item.e)}` +
        (right ? "" : `<br><a class="chlink" href="#${item.ch}" data-wrong-link="${item.ch}">Read ${esc(CHAPTERS[item.ch])} →</a>`);
      const dot = document.getElementById("dot" + n);
      dot.classList.remove("answered"); dot.classList.add(right ? "right" : "wrong");
    });

    const pct = score / QUESTIONS.length;
    let lvl, title, blurb;
    if (pct >= 0.8) { lvl = "lvl-ready"; title = PAGE.v1; blurb = PAGE.b1; }
    else if (pct >= 0.55) { lvl = "lvl-close"; title = "Nearly there. Brush up on a couple of chapters"; blurb = PAGE.b2; }
    else { lvl = "lvl-brush"; title = "Brush up first"; blurb = PAGE.b3; }

    resultBox.className = "result show " + lvl;
    const chItems = [...wrongChapters.entries()].map(([ch, qs]) =>
      `<li><a href="#${ch}" data-summary-link="${ch}">${esc(CHAPTERS[ch])}</a> <span class="small">(question${qs.length > 1 ? "s" : ""} ${qs.join(", ")})</span></li>`).join("");
    resultBox.innerHTML =
      `<div class="score" id="quiz-score">${score}<small> / ${QUESTIONS.length}</small></div>` +
      `<h3 id="quiz-verdict">${title}</h3><p>${blurb}</p>` +
      `<div class="result-note" id="quiz-disclaimer" role="note">${PAGE.disclaimer}</div>` +
      (chItems ? `<strong>Chapters to read:</strong><ul id="quiz-revisit">${chItems}</ul>` : `<p><strong>Perfect score.</strong> The chapters still have the worked numbers if you want to go deeper.</p>`) +
      `<div class="actions"><button class="btn btn-ghost" type="button" id="quiz-retake">↺ Retake the challenge</button><a class="btn btn-ghost" href="${PAGE.whereHref || "#where"}">${PAGE.whereLabel}</a></div>`;
    document.getElementById("quiz-retake").addEventListener("click", resetQuiz);
    document.getElementById("quiz-submit").style.display = "none";
    warn.style.display = "none";
    resultBox.scrollIntoView({ behavior: "smooth", block: "start" });
    try { localStorage.setItem("kinetic-" + PAGE.key + "-last", JSON.stringify({ score, of: QUESTIONS.length, at: Date.now() })); } catch (e) {}
  }

  function resetQuiz() {
    graded = false;
    resultBox.className = "result"; resultBox.innerHTML = "";
    document.querySelectorAll(".q").forEach(q => {
      q.className = "q";
      q.querySelector(".explain").innerHTML = "";
      q.querySelectorAll("input").forEach(i => { i.checked = false; i.disabled = false; });
      q.querySelectorAll(".opt").forEach(l => { l.className = "opt"; l.querySelector(".mark").textContent = ""; });
    });
    document.querySelectorAll("#quiz-dots a").forEach(d => d.className = "");
    const sub = document.getElementById("quiz-submit");
    sub.style.display = ""; delete sub.dataset.confirmed;
    updateProgress();
    document.getElementById("q1").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  document.getElementById("quiz-submit").addEventListener("click", grade);
  document.getElementById("quiz-reset").addEventListener("click", resetQuiz);
  updateProgress();

  // Expose for automated tests
  window.KINETIC_QUIZ = { QUESTIONS, CHAPTERS, grade, resetQuiz };


  // ---------- SNOWKITE LAB ----------
  // NASA Glenn troposphere: Ts = 15.04 − 0.00649h; p = 101.29 × ((Ts + 273.1)/288.08)^5.256 kPa.
  // Density uses the chosen air temperature: ρ = p / (0.2869 × (T + 273.1)). Reference: sea level, 15 °C.
  // q = ½ρv²; force scale = q × area. Apparent wind with the kite crossing at 2v: (√5 v)² / v² = 5. NWS wind chill (metric).
  (function () {
    const $ = id => document.getElementById(id);
    if (!$("sk-v")) return;
    const g = 9.81;
    const fmt = n => Math.round(n).toLocaleString("en-IN");
    const dens = (h, T) => { const Ts = 15.04 - 0.00649 * h, p = 101.29 * Math.pow((Ts + 273.1) / 288.08, 5.256); return [p, p / (0.2869 * (T + 273.1))]; };
    const REF = dens(0, 15)[1];
    const minus = n => (n < 0 ? "−" + Math.abs(n) : String(n));
    function update() {
      const v = +$("sk-v").value, A = +$("sk-A").value, h = +$("sk-h").value, T = +$("sk-T").value;
      $("sk-v-o").textContent = v + " km/h";
      $("sk-A-o").textContent = A + " m²";
      $("sk-h-o").textContent = fmt(h) + " m";
      $("sk-T-o").textContent = minus(T) + " °C";
      const [p, rho] = dens(h, T), ms = v / 3.6, q = 0.5 * rho * ms * ms, F = q * A;
      $("sk-p").textContent = p.toFixed(1) + " kPa";
      $("sk-rho").textContent = rho.toFixed(2) + " kg/m³";
      $("sk-q").textContent = q.toFixed(1) + " Pa";
      $("sk-F").textContent = fmt(F) + " N";
      $("sk-F-s").textContent = "≈ " + fmt(F / g) + " kg · ½ρv² × area";
      $("sk-rel").textContent = Math.round(rho / REF * 100) + "%";
      $("sk-gust").textContent = fmt(F * 2.25) + " N";
      $("sk-app").textContent = "5 ×";
      const V16 = Math.pow(v, 0.16), wc = 13.12 + 0.6215 * T - 11.37 * V16 + 0.3965 * T * V16;
      $("sk-wc").textContent = (T <= 10 && v >= 4.8 ? minus(Math.round(wc)) : minus(T)) + " °C";
      $("sk-bar").style.width = Math.min(100, rho / REF * 100).toFixed(0) + "%";
    }
    ["sk-v", "sk-A", "sk-h", "sk-T"].forEach(id => $(id).addEventListener("input", update));
    update();
  })();

  // ---------- LEVEL TABS ----------
  const tabs = document.querySelectorAll(".lvl-tabs button");
  tabs.forEach(btn => btn.addEventListener("click", () => {
    tabs.forEach(b => b.setAttribute("aria-selected", b === btn ? "true" : "false"));
    document.querySelectorAll(".lvl-panel").forEach(p => p.classList.toggle("show", p.id === btn.getAttribute("aria-controls")));
  }));

  // ---------- STICKY NAV ACTIVE STATE ----------
  const navLinks = [...document.querySelectorAll(".sectionnav a[href^='#']")];
  const targets = navLinks.map(a => document.querySelector(a.getAttribute("href"))).filter(Boolean);
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(entries => {
      entries.forEach(en => {
        if (en.isIntersecting) {
          navLinks.forEach(a => a.classList.toggle("active", a.getAttribute("href") === "#" + en.target.id));
        }
      });
    }, { rootMargin: "-45% 0px -50% 0px" });
    targets.forEach(t => io.observe(t));
  }

  // ---------- MOBILE NAV: edge fades + keep the active link in view ----------
  (function () {
    const snav = document.querySelector(".sectionnav");
    if (!snav) return;
    const fades = () => {
      const max = snav.scrollWidth - snav.clientWidth;
      snav.classList.toggle("fade-l", max > 4 && snav.scrollLeft > 4);
      snav.classList.toggle("fade-r", max > 4 && snav.scrollLeft < max - 4);
    };
    snav.addEventListener("scroll", fades, { passive: true });
    window.addEventListener("resize", fades);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fades);
    fades();
    const keep = () => {
      const a = snav.querySelector("a.active");
      if (!a || snav.scrollWidth <= snav.clientWidth + 4) return;
      const r = a.getBoundingClientRect(), n = snav.getBoundingClientRect();
      if (r.left < n.left + 16 || r.right > n.right - 40) snav.scrollBy({ left: r.left - n.left - 20, behavior: "smooth" });
    };
    if ("MutationObserver" in window) {
      const mo = new MutationObserver(keep);
      snav.querySelectorAll("a").forEach(a => mo.observe(a, { attributes: true, attributeFilter: ["class"] }));
    }
  })();
})();
